// 예봉중학교 (경기 남양주시) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by Yebong school local generator
// from candidate map/aerial outlines and school photos: every school building destructible; levels estimated,
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, YEBONG_PLACEMENTS, YEBONG_BUILDING_BASE, YEBONG_HEIGHT_GRIDS, YEBONG_HEIGHT_RANGE_M, YEBONG_ENV_IDS, YEBONG_DISPLAY, YEBONG_START_FRAME, YEBONG_OVERVIEW_AZIMUTH, YEBONG_CAMERA, YEBONG_PROVENANCE } from './data.js';
import { YEBONG_FOOTPRINTS } from './footprints.js';
import { YEBONG_PROTECTED } from './protected.js';
import { preserveYebongExteriorFinishes } from './facade-finish.js';

const MODEL_IDS = Object.freeze(YEBONG_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/yebong/${file}`, import.meta.url).href;
const HAZE = YEBONG_DISPLAY.haze, FADE = YEBONG_DISPLAY.fade;

export const YEBONG = Object.freeze({
  id: 'yebong',
  meta: Object.freeze({ school: '예봉중학교', campus: '남양주', short: '예봉중', modelNoun: '예봉중' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: YEBONG_PLACEMENTS,
  approvedCount: YEBONG_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600 ? { min: [-20,-5,-33], max: [22,11,24], azimuth: 1.52, elevationDegrees: 32 } : { min: [-23,-5,-29], max: [8,11,15], azimuth: 1.52, elevationDegrees: 17 }; }, overviewAzimuth: YEBONG_OVERVIEW_AZIMUTH }),
  camera: YEBONG_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: YEBONG_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: preserveYebongExteriorFinishes,
  }),
  terrain: Object.freeze({ heightGrids: YEBONG_HEIGHT_GRIDS, buildingBase: YEBONG_BUILDING_BASE, source: YEBONG_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: YEBONG_PROVENANCE, sourceNote: 'Candidate school and building outlines from map/aerial imagery; OSM surrounding roads; elevations and planting estimated'  }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: YEBONG_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'Yebong school local generator baked ground' }),
  }),
  protected: Object.freeze({ models: YEBONG_PROTECTED }),
  hazardTape: Object.freeze({ footprints: YEBONG_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: YEBONG_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default YEBONG;
